-- Account
cboe_c1options_binaryorderentry_boe_v2_10.account = {}

-- Size: Account
cboe_c1options_binaryorderentry_boe_v2_10.account.size = 16

-- Display: Account
cboe_c1options_binaryorderentry_boe_v2_10.account.display = function(value)
  -- Check if field has value
  if value == nil or value == '' then
    return "Account: No Value"
  end

  return "Account: "..value
end

-- Dissect: Account
cboe_c1options_binaryorderentry_boe_v2_10.account.dissect = function(buffer, offset, packet, parent)
  local length = cboe_c1options_binaryorderentry_boe_v2_10.account.size
  local range = buffer(offset, length)

  -- parse last octet
  local last = buffer(offset + length - 1, 1):uint()

  -- read full string or up to first zero
  local value = ''
  if last == 0 then
    value = range:stringz()
  else
    value = range:string()
  end

  local display = cboe_c1options_binaryorderentry_boe_v2_10.account.display(value, buffer, offset, packet, parent)

  parent:add(omi_cboe_c1options_binaryorderentry_boe_v2_10.fields.account, range, value, display)

  return offset + length, value
end

