cboe_c1options_binaryorderentry_boe_v2_10.order_origin.display = function(value)
  -- Check if field has value
  if value == nil or value == '' then
    return "Order Origin: No Value"
  end

  return "Order Origin: "..value
end

-- Dissect: Order Origin
cboe_c1options_binaryorderentry_boe_v2_10.order_origin.dissect = function(buffer, offset, packet, parent)
  local length = cboe_c1options_binaryorderentry_boe_v2_10.order_origin.size
  local range = buffer(offset, length)

  -- parse last octet
  local last = buffer(offset + length - 1, 1):uint()

  -- read full string or up to first zero
  local value = ''
  if last == 0 then
    value = range:stringz()
  else
    value = range:string()
  end

  local display = cboe_c1options_binaryorderentry_boe_v2_10.order_origin.display(value, buffer, offset, packet, parent)

  parent:add(omi_cboe_c1options_binaryorderentry_boe_v2_10.fields.order_origin, range, value, display)

  return offset + length, value
end

