  end

  local display = cboe_c1options_binaryorderentry_boe_v2_10.orig_cl_ord_id.display(value, buffer, offset, packet, parent)

  parent:add(omi_cboe_c1options_binaryorderentry_boe_v2_10.fields.orig_cl_ord_id, range, value, display)

  return offset + length, value
end

-- Orig Time
