-- Size: Orig Time
cboe_c1options_binaryorderentry_boe_v2_10.orig_time.size = 8

-- Display: Orig Time
cboe_c1options_binaryorderentry_boe_v2_10.orig_time.display = function(value)
  -- Parse unix nanosecond timestamp
  local seconds = (value / UInt64(1000000000)):tonumber()
  local nanoseconds = (value % UInt64(1000000000)):tonumber()

  return "Orig Time: "..os.date("%Y-%m-%d %H:%M:%S.", seconds)..string.format("%09d", nanoseconds)
end

