-- Size: Quote Result Group
cboe_c1options_binaryorderentry_boe_v2_10.quote_result_group.size =
  cboe_c1options_binaryorderentry_boe_v2_10.order_id.size + 
  cboe_c1options_binaryorderentry_boe_v2_10.quote_result.size + 
  cboe_c1options_binaryorderentry_boe_v2_10.quote_liquidity_indicator.size + 
  cboe_c1options_binaryorderentry_boe_v2_10.reserved_6.size

-- Display: Quote Result Group
cboe_c1options_binaryorderentry_boe_v2_10.quote_result_group.display = function(packet, parent, length)
  return ""
end

-- Dissect Fields: Quote Result Group
cboe_c1options_binaryorderentry_boe_v2_10.quote_result_group.fields = function(buffer, offset, packet, parent, quote_result_group_index)
  local index = offset

  -- Implicit Quote Result Group Index
  if quote_result_group_index ~= nil and show.indexes then
    local iteration = parent:add(omi_cboe_c1options_binaryorderentry_boe_v2_10.fields.quote_result_group_index, quote_result_group_index)
    iteration:set_generated()
  end

  -- Order Id: Binary
  index, order_id = cboe_c1options_binaryorderentry_boe_v2_10.order_id.dissect(buffer, index, packet, parent)

  -- Quote Result: Text
  index, quote_result = cboe_c1options_binaryorderentry_boe_v2_10.quote_result.dissect(buffer, index, packet, parent)

  -- Quote Liquidity Indicator: Text
  index, quote_liquidity_indicator = cboe_c1options_binaryorderentry_boe_v2_10.quote_liquidity_indicator.dissect(buffer, index, packet, parent)

  -- Reserved 6: Reserved
  index, reserved_6 = cboe_c1options_binaryorderentry_boe_v2_10.reserved_6.dissect(buffer, index, packet, parent)

  return index
end

-- Dissect: Quote Result Group
cboe_c1options_binaryorderentry_boe_v2_10.quote_result_group.dissect = function(buffer, offset, packet, parent, quote_result_group_index)
  if show.repeating_groups then
    -- Optionally add element to protocol tree
    parent = parent:add(omi_cboe_c1options_binaryorderentry_boe_v2_10.fields.quote_result_group, buffer(offset, 0))
    local index = cboe_c1options_binaryorderentry_boe_v2_10.quote_result_group.fields(buffer, offset, packet, parent, quote_result_group_index)
    local length = index - offset
    parent:set_len(length)
    local display = cboe_c1options_binaryorderentry_boe_v2_10.quote_result_group.display(packet, parent, length)
    parent:append_text(display)

    return index, parent
  else
    -- Skip element, add fields directly
    return cboe_c1options_binaryorderentry_boe_v2_10.quote_result_group.fields(buffer, offset, packet, parent, quote_result_group_index)
  end
end

