end

-- Dissect Fields: Quote Update Acknowledgment Message
cboe_c1options_binaryorderentry_boe_v2_10.quote_update_acknowledgment_message.fields = function(buffer, offset, packet, parent, size_of_quote_update_acknowledgment_message)
  local index = offset

  -- Transaction Time: DateTime
  index, transaction_time = cboe_c1options_binaryorderentry_boe_v2_10.transaction_time.dissect(buffer, index, packet, parent)

  -- Quote Update Id: Text
  index, quote_update_id = cboe_c1options_binaryorderentry_boe_v2_10.quote_update_id.dissect(buffer, index, packet, parent)

  -- Quote Reject Reason: Text
  index, quote_reject_reason = cboe_c1options_binaryorderentry_boe_v2_10.quote_reject_reason.dissect(buffer, index, packet, parent)

  -- Reserved 17: Reserved
  index, reserved_17 = cboe_c1options_binaryorderentry_boe_v2_10.reserved_17.dissect(buffer, index, packet, parent)

  -- Number Of Quote Results: Binary
  index, number_of_quote_results = cboe_c1options_binaryorderentry_boe_v2_10.number_of_quote_results.dissect(buffer, index, packet, parent)

  -- Repeating: Quote Result Group
  for quote_result_group_index = 1, number_of_quote_results do
    index, quote_result_group = cboe_c1options_binaryorderentry_boe_v2_10.quote_result_group.dissect(buffer, index, packet, parent, quote_result_group_index)
  end

  return index
end

-- Dissect: Quote Update Acknowledgment Message
cboe_c1options_binaryorderentry_boe_v2_10.quote_update_acknowledgment_message.dissect = function(buffer, offset, packet, parent, size_of_quote_update_acknowledgment_message)
  local size_of_quote_update_acknowledgment_message = cboe_c1options_binaryorderentry_boe_v2_10.quote_update_acknowledgment_message.size(buffer, offset)
  local index = offset + size_of_quote_update_acknowledgment_message

  -- Optionally add group/struct element to protocol tree
  if show.application_messages then
    parent = parent:add(omi_cboe_c1options_binaryorderentry_boe_v2_10.fields.quote_update_acknowledgment_message, buffer(offset, 0))
    local current = cboe_c1options_binaryorderentry_boe_v2_10.quote_update_acknowledgment_message.fields(buffer, offset, packet, parent, size_of_quote_update_acknowledgment_message)
    parent:set_len(size_of_quote_update_acknowledgment_message)
    local display = cboe_c1options_binaryorderentry_boe_v2_10.quote_update_acknowledgment_message.display(buffer, packet, parent)
    parent:append_text(display)

    return index, parent
  else
    -- Skip element, add fields directly
    cboe_c1options_binaryorderentry_boe_v2_10.quote_update_acknowledgment_message.fields(buffer, offset, packet, parent, size_of_quote_update_acknowledgment_message)

